<script setup lang="ts">import{onMounted,ref}from'vue';import{Activity,MapPinned,TrainFront,Wifi}from'lucide-vue-next';import{api}from'@/services/api';const stationCount=ref(0),trainCount=ref(0),activeStations=ref(0),activeTrains=ref(0);onMounted(async()=>{const[s,t]=await Promise.all([api.adminStations(),api.trains()]);stationCount.value=s.length;trainCount.value=t.length;activeStations.value=s.filter(x=>x.status===1).length;activeTrains.value=t.filter(x=>x.status===1).length})</script>
<template><section class="admin-page"><header class="page-head"><div><p class="eyebrow">OVERVIEW</p><h1>运营数据概览</h1><p>早上好，这里是当前铁路基础数据状态。</p></div><span class="online"><Wifi/>系统运行正常</span></header><div class="metric-grid"><article><span><MapPinned/></span><div><small>车站总数</small><strong>{{stationCount}}</strong><p>{{activeStations}} 个已启用</p></div></article><article><span><TrainFront/></span><div><small>车次总数</small><strong>{{trainCount}}</strong><p>{{activeTrains}} 个已启用</p></div></article><article><span><Activity/></span><div><small>车站启用率</small><strong>{{stationCount?Math.round(activeStations/stationCount*100):0}}%</strong><p>基础服务可用</p></div></article></div><div class="admin-welcome"><div><p class="eyebrow">QUICK START</p><h2>从基础数据开始配置</h2><p>先维护车站和车次，再进入车次详情配置经停路线、运行计划、票价与库存。</p><div><RouterLink class="btn primary" to="/admin/stations">管理车站</RouterLink><RouterLink class="btn ghost" to="/admin/trains">管理车次</RouterLink></div></div><TrainFront/></div></section></template>
